/**
 * Pinned results shown on the public site.
 *
 * `results.json` is generated by `scripts/export_site_snapshot.py` from the git tag
 * `site-pin-ppo-lstm`, never from the working tree, so later research cannot change it.
 * Implementation shortfall (IS) is in % of arrival value; higher is better.
 */
import raw from './results.json'

export type Regime = 'crash' | 'normal' | 'calm'
export type Split = 'train' | 'held_out'
export type StrategyKey = 'twap' | 'heuristic' | 'ac_optimal' | 'adaptive_ac' | 'rl'

export interface StrategyResult {
  mean: number
  std: number
  cvar95: number
  episodes: number[]
}

export interface DateResult {
  date: string
  regime: Regime
  split: Split
  event: string
  event_detail: string
  strategies: Record<StrategyKey, StrategyResult>
}

export interface AblationRow {
  date: string
  regime: Regime
  split: Split
  rl12: number
  rl16: number
  ac: number
  delta16: number
  delta16_lo: number
  delta16_hi: number
  delta12: number
}

export interface PinnedResults {
  model: {
    name: string
    variant: string
    algorithm: string
    checkpoint: string
    pinned_tag: string
    pinned_commit: string
  }
  protocol: { episodes_per_strategy: number; metric: string; venue: string }
  strategies: { key: StrategyKey; label: string }[]
  events: Record<string, string>
  dates: DateResult[]
  ablation: AblationRow[]
}

export const PINNED = raw as PinnedResults

export const REGIMES: Regime[] = ['crash', 'normal', 'calm']

export const STRATEGY_COLORS: Record<StrategyKey, string> = {
  twap: '#94A3B8',
  heuristic: '#64748B',
  ac_optimal: '#6366F1',
  adaptive_ac: '#3B82F6',
  rl: '#10B981',
}

export const REGIME_COLORS: Record<Regime, string> = {
  crash: '#EF4444',
  normal: '#F59E0B',
  calm: '#38BDF8',
}

/** RL minus AC Optimal, in percentage points (> 0: the RL agent sold at a better price). */
export function edgeVsAc(d: DateResult): number {
  return d.strategies.rl.mean - d.strategies.ac_optimal.mean
}

export function filterDates(dates: DateResult[], split: Split | 'all', regime: Regime | 'all'): DateResult[] {
  return dates.filter(d => (split === 'all' || d.split === split) && (regime === 'all' || d.regime === regime))
}

export interface RegimeSummary {
  regime: Regime
  days: number
  wins: number
  meanEdge: number
  bestEdge: number
}

export function summariseByRegime(dates: DateResult[]): RegimeSummary[] {
  return REGIMES.map(regime => {
    const edges = dates.filter(d => d.regime === regime).map(edgeVsAc)
    return {
      regime,
      days: edges.length,
      wins: edges.filter(e => e > 0).length,
      meanEdge: edges.length ? edges.reduce((a, b) => a + b, 0) / edges.length : 0,
      bestEdge: edges.length ? Math.max(...edges) : 0,
    }
  }).filter(s => s.days > 0)
}

/** Mean IS of every strategy within each regime, for the grouped bar chart. */
export function strategyMeansByRegime(dates: DateResult[]) {
  return REGIMES.map(regime => {
    const ds = dates.filter(d => d.regime === regime)
    const row: Record<string, string | number> = { regime }
    for (const s of PINNED.strategies) {
      row[s.label] = ds.length ? ds.reduce((a, d) => a + d.strategies[s.key].mean, 0) / ds.length : 0
    }
    return { row, n: ds.length }
  }).filter(r => r.n > 0).map(r => r.row)
}

/** Histogram of episode IS for the given strategies on one date, on shared bins. */
export function episodeHistogram(d: DateResult, keys: StrategyKey[], bins = 16) {
  const all = keys.flatMap(k => d.strategies[k].episodes)
  const lo = Math.min(...all)
  const hi = Math.max(...all)
  const width = (hi - lo) / bins || 1
  return Array.from({ length: bins }, (_, i) => {
    const from = lo + i * width
    const row: Record<string, number | string> = { bin: (from + width / 2).toFixed(2) }
    for (const k of keys) {
      row[k] = d.strategies[k].episodes.filter(v =>
        v >= from && (i === bins - 1 ? v <= hi : v < from + width)).length
    }
    return row
  })
}
